    make(4, "計算 −2.4＋1.7 的值。", {"A": "−4.1", "B": "−0.7", "C": "0.7", "D": "4.1"}, "B", "異號相加取差 2.4−1.7＝0.7，絕對值較大的 −2.4 決定負號，因此為 −0.7，選 B。", "先對齊小數位，再用異號加法規則判斷差值與符號。", ["確認 −2.4 與 1.7 是異號小數。", "計算絕對值差 2.4−1.7＝0.7。", "比較絕對值，2.4 較大且帶負號。", "得到 −0.7。", "選 B，計算 −0.7−1.7＝−2.4 回驗。"], "easy"),
    make(5, "計算 6−[2−(−3)] 的值。", {"A": "1", "B": "5", "C": "7", "D": "11"}, "A", "括號內 2−(−3)＝5，外式為 6−5＝1，所以選 A。", "由內而外處理括號，並先把減負數改寫成加法。", ["先計算內層 2−(−3)。", "將減去負數改成 2＋3＝5。", "原式變成 6−5。", "計算得到 1。", "選 A，確認外層負號沒有誤分配到括號內各項。"], "medium"),
    make(6, "計算 (−3／5)÷(9／10) 的值。", {"A": "−2／3", "B": "−3／2", "C": "2／3", "D": "3／2"}, "A", "除以分數等於乘以倒數：(−3／5)×(10／9)＝−30／45＝−2／3，選 A。", "分數除法先改乘倒數，再約分並保留負號。", ["將除數 9／10 取倒數為 10／9。", "改寫成 (−3／5)×(10／9)。", "約分 10 與 5、3 與 9 的公因數。", "得到 −2／3。", "選 A，負數除以正數結果仍為負。"], "hard"),
    make(7, "計算 2／3＋(−1／4)×8 的值。", {"A": "−4／3", "B": "−2／3", "C": "2／3", "D": "8／3"}, "A", "先算乘法 (−1／4)×8＝−2，再算 2／3−2＝2／3−6／3＝−4／3，選 A。", "先乘除後加減，整數可先改寫成同分母分數再相加。", ["先計算 (−1／4)×8＝−2。", "原式變成 2／3−2。", "把 2 寫成 6／3。", "計算 2／3−6／3＝−4／3。", "選 A，估算 0.67−2 約為 −1.33 作合理性檢查。"], "hard"),
